import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.emssim.generictabular import GenericEMSSIMCommand

__author__ = "Sylwester Golonka"
__copyright__ = "Copyright (C) 2018, Nokia"
__email__ = "sylwester.golonka@nokia.com"


class PlanShow(GenericEMSSIMCommand):
    """Planshow command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Planshow command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(PlanShow, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "plan_show"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_headers(line)
                self._parse_line(line)
            except ParsingDone:
                pass
        return super(PlanShow, self).on_new_line(line, is_full_line)

    _re_parse = re.compile(r"\s*\|\s*(?P<OBJECT>\S*)\s*\|\s*(?P<ATTRIBUTE>\S*)\s*\|\s*(?P<VALUE>\S*)\s*\|\s*(?P<OPERATION>\S*)\s*\|")

    def _parse_line(self, line):
        if self._regex_helper.search_compiled(PlanShow._re_parse, line):
            if not self._regex_helper.group("OBJECT") in self.current_ret:
                self.current_ret[self._regex_helper.group("OBJECT")] = {}
            self.current_ret[self._regex_helper.group("OBJECT")][self._regex_helper.group("ATTRIBUTE")] = {}
            self.current_ret[self._regex_helper.group("OBJECT")][self._regex_helper.group("ATTRIBUTE")]["VALUE"] = self._regex_helper.group("VALUE")
            self.current_ret[self._regex_helper.group("OBJECT")][self._regex_helper.group("ATTRIBUTE")]["OPERATION"] = self._regex_helper.group(
                "OPERATION"
            )

    _re_parse_headers = re.compile(r"\|\s*OBJECT\s*\|\s*ATTRIBUTE\s*\|\s*VALUE\s*\|\s*OPERATION\s*\|")

    def _parse_headers(self, line):
        if self._regex_helper.search_compiled(PlanShow._re_parse_headers, line):
            raise ParsingDone

    _re_parse_error = re.compile(r"(?P<ERROR>Empty plan|Plan wasn\'t created yet)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(PlanShow._re_parse_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone


